public static class AddBasketballSeams {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit required");const string path="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/BasketballSeams.asset";if(AssetDatabase.LoadAssetAtPath<Mesh>(path)!=null)throw new Exception("Already installed");var vertices=new List<Vector3>();var triangles=new List<int>();for(int ring=0;ring<3;ring++){Vector3 normal=ring==0?Vector3.up:ring==1?Vector3.right:Vector3.forward;Vector3 u=ring==0?Vector3.right:Vector3.up;Vector3 v=Vector3.Cross(normal,u);int start=vertices.Count;for(int i=0;i<=48;i++){float angle=i*Mathf.PI*2/48;Vector3 center=(Mathf.Cos(angle)*u+Mathf.Sin(angle)*v)*.211f;vertices.Add((center+normal*.004f).normalized*.212f);vertices.Add((center-normal*.004f).normalized*.212f);if(i<48){int n=start+i*2;triangles.AddRange(new[]{n,n+2,n+1,n+1,n+2,n+3});}}}var mesh=new Mesh{name="Basketball seam ribbons"};mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/ShoeTower.unity");var d=Object.FindFirstObjectByType<Chapter45Director>();File.Copy(d.gameObject.scene.path,"outputs/chapter45-detailed-design-2026-10-03/scene-recovery/ShoeTower-before-ball-seams.unity",false);int count=0;foreach(var role in d.encounters.SelectMany(e=>e.actors).Select(a=>a.GetComponent<Chapter45RoleAction>()).Where(b=>b!=null&&b.role==Chapter45RoleAction.Role.Basketball)){var g=new GameObject("Basketball leather seams");g.transform.SetParent(role.heldProp,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=g.AddComponent<MeshRenderer>();renderer.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedMall-20261003T092859667/Ink graphite.mat");renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;count++;}EditorSceneManager.MarkSceneDirty(d.gameObject.scene);EditorSceneManager.SaveScene(d.gameObject.scene);AssetDatabase.SaveAssets();return new{count,triangles=triangles.Count/3,collidersAdded=0,provenance="Native functional hand-prop detail; does not replace generated environment or character models."};}}
